/* Standalone Figma Development Plugin. No network, no MCP execution, no original-page mutations.
 * Standard Plugin API only: createFrame + layoutMode implements native Auto Layout.
 * The MCP-only createAutoLayout/query/set helpers are intentionally not used here.
 */
'use strict';
const T = BUNDLE.tokens;
const RUN = BUNDLE.runName;
const W = T.canvas.width, H = T.canvas.height, CW = W - 32;
const KIT = {}, ICON = {}, VAR = {}, STYLE = {}, PENDING_LINKS = [], STYLE_JOBS = [];
const LEDGER = {runName: RUN, cloudExecuted: false, status: 'not-run', pages: {}, components: {}, componentSets: {}, variables: {}, styles: {}, screens: {}, overlays: {}, sourceReferences: {}, warnings: [], checks: {}};
let PAGE, LIBRARY, OVERLAYS, busy = false, stopRequested = false, libraryY = 72, overlayIndex = 0;
function progress(text, value) { figma.ui.postMessage({type:'progress', text, value}); }
function rgb(hex) { return {r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255}; }
function solid(key,opacity=1) { const p={type:'SOLID',color:rgb(T.colors[key]||key),opacity}; return opacity===1&&VAR['color/'+key] ? figma.variables.setBoundVariableForPaint(p,'color',VAR['color/'+key]) : p; }
function fill(n,key,opacity=1) { n.fills=key?[solid(key,opacity)]:[]; }
function border(n,key='border',weight=1) { n.strokes=[solid(key)];n.strokeWeight=weight; }
function radius(n,key) { n.cornerRadius=T.radius[key]===undefined?key:T.radius[key];if(VAR['radius/'+key])n.setBoundVariable('cornerRadius',VAR['radius/'+key]); }
function bounds(n,w,h) { n.resize(w,Math.max(1,h));return n; }
function frame(p,name,w,h,color) { const n=figma.createFrame();n.name=name;bounds(n,w,h);n.clipsContent=false;fill(n,color);p.appendChild(n);return n; }
function auto(p,name,w,dir='VERTICAL',gap=6,color) {const n=frame(p,name,w,1,color);n.layoutMode=dir;n.primaryAxisSizingMode='AUTO';n.counterAxisSizingMode='FIXED';n.itemSpacing=gap;if(VAR['space/within']&&gap===6)n.setBoundVariable('itemSpacing',VAR['space/within']);return n;}
function horizontal(p,name,w,gap=8){const n=auto(p,name,w,'HORIZONTAL',gap);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='AUTO';n.counterAxisAlignItems='CENTER';return n;}
function pad(n,value=16){n.paddingLeft=value;n.paddingRight=value;n.paddingTop=value;n.paddingBottom=value;if(VAR['space/page']&&value===16)for(const k of ['paddingLeft','paddingRight','paddingTop','paddingBottom'])n.setBoundVariable(k,VAR['space/page']);}
function absolute(n,x,y){if(n.parent&&'layoutMode'in n.parent&&n.parent.layoutMode!=='NONE')n.layoutPositioning='ABSOLUTE';n.x=x;n.y=y;return n;}
function text(p,value,w,role='body',color='text',weight='Regular'){const n=figma.createText();n.name=role;n.fontName={family:T.font.family,style:weight};n.fontSize=T.font[role]||T.font.body;n.lineHeight={unit:'PERCENT',value:135};n.characters=String(value||'');n.resize(w,Math.max(16,(T.font[role]||14)*1.35));n.textAutoResize='HEIGHT';fill(n,color);p.appendChild(n);const style=STYLE[role+'/'+weight];if(style)STYLE_JOBS.push(n.setTextStyleIdAsync(style.id).then(()=>{fill(n,color);}));return n;}
function ctext(c,p,name,value,w,role='body',color='text',weight='Regular'){const t=text(p,value,w,role,color,weight);t.name=name;const key=c.addComponentProperty(name,'TEXT',String(value||''));t.componentPropertyReferences={characters:key};return t;}
function cvisible(c,node,name,visible=true){const key=c.addComponentProperty(name,'BOOLEAN',visible);node.componentPropertyReferences={...(node.componentPropertyReferences||{}),visible:key};node.visible=visible;}
function component(name,w=328){const c=figma.createComponent();c.name=name;c.resize(w,1);c.layoutMode='VERTICAL';c.primaryAxisSizingMode='AUTO';c.counterAxisSizingMode='FIXED';c.itemSpacing=6;fill(c);c.clipsContent=false;LIBRARY.appendChild(c);return c;}
function register(name,c){KIT[name]=c;LEDGER.components[name]=c.id;c.description='Gensen UI refactor · '+name+'. Edit semantic text properties; keep title, quantity, state and effect separate.';absolute(c,24,libraryY);libraryY+=c.height+48;return c;}
function variantSet(name,variants){const set=figma.combineAsVariants(variants,LIBRARY);set.name='Gensen Refactor/'+name;set.description='Semantic variants for '+name+'. One primary command per player viewport.';let y=24,mx=0;for(const c of variants){c.x=24;c.y=y;y+=c.height+20;mx=Math.max(mx,c.width);}set.resizeWithoutConstraints(mx+48,y);set.x=24;set.y=libraryY;libraryY+=y+48;LEDGER.componentSets[name]=set.id;return set;}
function propKeys(main){const owner=main.parent&&main.parent.type==='COMPONENT_SET'?main.parent:main;return Object.keys(owner.componentPropertyDefinitions||{});}
function inst(p,name,properties={},w){const main=KIT[name];if(!main)throw Error('Missing component '+name);const n=main.createInstance();p.appendChild(n);n.name=name;const used=main.findAll(n=>Boolean(n.componentPropertyReferences)).flatMap(n=>Object.values(n.componentPropertyReferences));const keys=[...used,...propKeys(main)],vals={};for(const [key,val]of Object.entries(properties)){const full=keys.find(k=>k.split('#')[0]===key);if(full)vals[full]=val;}if(Object.keys(vals).length)n.setProperties(vals);if(w){n.resize(w,n.height);n.primaryAxisSizingMode=main.primaryAxisSizingMode;n.counterAxisSizingMode=main.counterAxisSizingMode;}return n;}
function inferIcon(o){if(o.icon&&ICON[o.icon])return o.icon;const key=(o.title||o.name||'').toLowerCase();if(BUNDLE.assetNames[key]&&ICON[BUNDLE.assetNames[key]])return BUNDLE.assetNames[key];const rules=[[/seed/,'i-radish-seeds'],[/fish|perch|crucian|pike|eel/,'i-fish'],[/wood|timber/,'i-wood'],[/stone|quartz/,'i-stone'],[/copper/,'i-copper'],[/reeds?/,'i-reeds'],[/herb/,'i-herb'],[/salt/,'i-salt'],[/torch/,'i-torch'],[/compost/,'i-compost'],[/trap/,'i-trap'],[/pick/,'i-pickaxe'],[/rod|fishing/,'i-rod'],[/hoe|farming/,'i-hoe'],[/sword|combat/,'i-sword'],[/ring/,'i-ring'],[/charm/,'i-charm'],[/cook|stove|dish|meal|soup|grilled/,'i-pot'],[/farm|home/,'i-home'],[/bag|parcel|storage|cabinet/,'i-bag'],[/passport|permit|ticket/,'i-passport'],[/travel|tokyo/,'i-travel'],[/energy/,'i-energy'],[/coin/,'i-coin']];return rules.find(r=>r[0].test(key))?.[1]||'i-question';}
function icon(p,key,size=28){const main=ICON[key]||ICON['i-question'];const n=main.createInstance();p.appendChild(n);n.rescale(size/main.width);n.name='Icon/'+key;return n;}
function cicon(c,p,key,size=28,field='Icon'){const n=icon(p,key,size);const k=c.addComponentProperty(field,'INSTANCE_SWAP',n.mainComponent.id);n.componentPropertyReferences={mainComponent:k};return n;}
function line(p,w=CW){const n=frame(p,'Divider',w,1,'border');return n;}
function button(p,a,emphasis='secondary',ownerId){const kind=a.kind||'navigate';let key=kind==='navigate'?'NavigationRow':kind==='dismiss'?'Dismiss':kind==='blocked'?'Command/blocked':kind==='destructive'?(emphasis==='primary'?'Command/destructive':'Command/danger-secondary'):emphasis==='primary'?'Command/primary':'Command/secondary';const n=inst(p,key,{Label:a.label||'Continue'},p.width);n.name=key+' · '+a.label;if(a)PENDING_LINKS.push({node:n,action:a,ownerId});return n;}
function heading(p,s,w=p.width){return inst(p,'ObjectHeader',{Title:s.title||'',State:s.state||'','Show state':Boolean(s.state),Effect:s.effect||'','Show effect':Boolean(s.effect),Quantity:s.quantity?.value||'','Quantity label':s.quantity?.label||'','Show quantity':Boolean(s.quantity)},w);}
function factNode(p,f,w=p.width){return inst(p,(f.kind==='cost'?'Cost':'Fact'),{Label:f.label||'',Value:String(f.value??''),'Kind':f.kind||'progress'},w);}
function facts(p,list){for(const f of list||[])factNode(p,f);}
function needs(p,list,ownerId){if(!list?.length)return;const wrap=auto(p,'Requirements',p.width,'VERTICAL',10);for(let i=0;i<list.length;i+=3){const r=horizontal(wrap,'Requirement row',p.width,8);for(const q of list.slice(i,i+3)){const key=q.title||q.label||'Requirement';const short=q.have!==undefined&&q.need!==undefined&&q.have<q.need;const n=inst(r,short?'NeedTile/short':'NeedTile/met',{Title:key,Value:q.level!==undefined?'Lv'+q.level:String(q.have??'?')+'/'+String(q.need??'?'),Icon:(ICON[q.icon]||ICON[inferIcon({title:key})]).id},(p.width-16)/3);PENDING_LINKS.push({node:n,ownerId,detail:{title:key,state:short?'Short':'Requirement',effect:q.level!==undefined?'Reach this level to unlock.':q.source&&q.source!=='Inventory'?'From '+q.source:'Check your materials.',keyFacts:[{label:'Have',value:String(q.have??'—')},{label:'Need',value:String(q.need??q.level??'—')}],actions:[{label:'Close',kind:'dismiss'}]}});}}}
function semanticRow(p,r,ownerId){const n=inst(p,'ItemRow',{Title:r.title||r.label||'',State:r.state||'','Show state':Boolean(r.state),Effect:r.effect||'','Show effect':Boolean(r.effect),Quantity:r.quantity?.value||'','Quantity label':r.quantity?.label||'','Show quantity':Boolean(r.quantity),Icon:(ICON[r.icon]||ICON[inferIcon(r)]).id},p.width);if(r.keyFacts?.length){const f=auto(p,'Row facts',p.width,'VERTICAL',4);for(const q of r.keyFacts)factNode(f,q);}if(r.actions?.length){for(const a of r.actions){button(p,a,'secondary',ownerId);PENDING_LINKS[PENDING_LINKS.length-1].itemContext=r;}}else if(r.disclosure?.length)PENDING_LINKS.push({node:n,ownerId,detail:r});return n;}
