function worldPlace(s,d={}){const explicit=d.place||(s.navigation?.placeExplicit!==false?s.navigation?.place:null);if(explicit)return explicit;const key=sceneKey(s);if(/^farm/.test(key))return 'Homestead';if(/^pond/.test(key))return 'Willow Pond';if(/^kitchen/.test(key))return 'Kitchen';if(/^mine/.test(key))return 'Mine';if(/^map/.test(key))return 'City map';return ({'tea-house':'Tea House','tackle-shop':'Tackle Shop','market-square-v2':'Market Square','travel-post':'Travel Post','trading-post':'Trading Post'})[key]||'Homestead';}
