function sceneScreen(p,s){const footer=bottom(p,s,s.id);const compact=auto(p,'Scene context',CW,'VERTICAL',8,'surface');compact.x=16;compact.y=122;radius(compact,'card');heading(compact,s);facts(compact,(s.keyFacts||[]).filter(f=>f.kind!=='cost'));if(s.sceneState?.placement){const area=frame(p,'Placement footprint',s.sceneState.footprint===4?144:108,s.sceneState.footprint===4?144:108,'primaryTint');area.opacity=.55;border(area,'primary',2);area.x=(W-area.width)/2;area.y=360;}if(s.sceneState?.stoveStates){const stages=auto(p,'Independent stoves',CW,'VERTICAL',6);stages.x=16;stages.y=Math.max(300,compact.y+compact.height+12);s.sceneState.stoveStates.forEach((v,i)=>semanticRow(stages,{title:'Stove '+(i+1),state:v,icon:'i-pot'},s.id));}if(s.presentation?.feedback==='nonmodal-toast'){const t=inst(p,'Toast',{Message:s.title+' '+s.state.toLowerCase()+'. '+s.effect});absolute(t,16,630);}
 const navigation=(s.actions||[]).filter(a=>a.kind==='navigate');if(navigation.length){const nav=auto(p,'Scene destinations',CW,'VERTICAL',0,'surface');nav.x=16;for(const a of navigation)button(nav,a,'secondary',s.id);nav.y=Math.max(compact.y+compact.height+12,footer.y-nav.height-92);radius(nav,'card');}if(!s.sceneState?.placement&&!['map','kitchen'].includes(sceneKey(s))){const quick=auto(p,'Scene Quick Bar',336);quick.x=12;quick.y=708;quickbar(quick,s,s.id);}if(s.items?.length){const y=compact.y+compact.height+12;const entries=scroll(p,'Scene object entries',16,y,CW,Math.max(80,footer.y-y-88));for(const it of s.items)semanticRow(entries.content,it,s.id);}if(s.disclosure?.length){PENDING_LINKS.push({node:compact,ownerId:s.id,detail:{title:s.title,state:s.state,disclosure:s.disclosure,actions:[{label:'Close',kind:'dismiss'}]}});}}
