function buildScreen(s,index){const box=figma.createSection();box.name='Review · '+s.id;PAGE.appendChild(box);box.resizeWithoutConstraints(360,1000);fill(box);box.x=100+(index%8)*412;box.y=180+Math.floor(index/8)*1070;const screen=frame(box,s.id+' · '+s.title,W,H,'surface');screen.clipsContent=true;scene(screen,s);const reference=s.layout==='states'||s.reviewOnly;if(!reference)hud(screen,s);if(reference)states(screen,s);else if(s.layout==='gear')gearScreen(screen,s);else if(s.variant==='shop-with-bag')shop(screen,s);else if(s.variant==='cookbook-with-scene-pot'||s.variant==='experiment-with-scene-pot')kitchen(screen,s,s.variant.startsWith('experiment'));else if(s.variant==='collection-grid')collection(screen,s);else if(s.layout==='inventory')inventory(screen,s);else if(s.layout==='profile')profile(screen,s);else if(s.layout==='scene')sceneScreen(screen,s);else general(screen,s);reviewNote(box,s,816);LEDGER.screens[s.id]=screen.id;LEDGER.sourceReferences[s.id]={...(LEDGER.sourceReferences[s.id]||{}),sourceNodeId:s.sourceRef?.nodeId||s.figmaNodeId||null,newNodeId:screen.id,sourceFile:s.sourceRef?.file||s.sourceHtml,sourceGroup:s.sourceGroup,layout:s.layout,variant:s.variant||null,reviewOnly:Boolean(s.reviewOnly||s.layout==='states'),stateExamples:(s.stateExamples||[]).length};return screen;}
const DETAIL_CACHE=new Map();
