function createDetail(detail,ownerId){const cacheKey=ownerId+'|'+JSON.stringify(detail);if(DETAIL_CACHE.has(cacheKey))return DETAIL_CACHE.get(cacheKey);const o=overlayFrame(detail.title||'Details');DETAIL_CACHE.set(cacheKey,o);const header=auto(o,'Detail identity',CW);header.x=16;header.y=16;heading(header,detail);const dismiss=inst(o,'Dismiss',{Label:'Close'});absolute(dismiss,16,560);PENDING_LINKS.push({node:dismiss,close:true});const y=16+header.height+16;const body=scroll(o,'Detail body',16,y,CW,Math.max(80,548-y));facts(body.content,detail.keyFacts);needs(body.content,detail.requirements,ownerId);if(detail.supporting)text(body.content,detail.supporting,CW);for(const r of [...(detail.rows||[]),...(detail.items||[])])semanticRow(body.content,r,ownerId);for(const d of detail.disclosure||[])text(body.content,d,CW);for(const a of detail.actions||[])if(a.kind!=='dismiss'){button(body.content,a,'secondary',ownerId);PENDING_LINKS[PENDING_LINKS.length-1].itemContext=detail;}LEDGER.overlays[o.id]={title:detail.title,ownerId,type:'information'};return o;}
function createToast(message,ownerId){const cacheKey='toast|'+message;if(DETAIL_CACHE.has(cacheKey))return DETAIL_CACHE.get(cacheKey);const o=overlayFrame('Feedback',H);DETAIL_CACHE.set(cacheKey,o);fill(o);const t=inst(o,'Toast',{Message:message});absolute(t,16,H-176);const close=inst(o,'Dismiss',{Label:'Got it'});absolute(close,16,H-80);LEDGER.overlays[o.id]={title:message,ownerId,type:'toast'};PENDING_LINKS.push({node:close,close:true});PENDING_LINKS.push({node:o,close:true,timeout:2.5});return o;}
function contextDetail(action){const c=action.context||{};if(c.resident)return {title:c.resident,state:action.label==='Talk'?'Conversation':'Choose a dish',effect:action.label==='Talk'?'Spend a moment with '+c.resident+'.':'Select a dish from your bag.',items:action.label==='Talk'?[]:[{title:'Herb Grilled Fish',state:'Good',quantity:{value:'1',label:'Owned'},effect:'A warm grilled fish dish.'}],actions:[{label:'Close',kind:'dismiss'}]};if(c.overlay==='facility-coverage')return {title:c.facility||'Coverage',state:'Placed',effect:'Waters the eight surrounding plots.',keyFacts:[{label:'Coverage',value:'8 plots',kind:'capacity'},{label:'Growth time',value:'15% faster',kind:'reward'}],actions:[{label:'Close',kind:'dismiss'}]};if(c.overlay==='map')return {title:c.targetType||'Visited ponds',state:'Map',effect:c.targetType?'Find '+c.targetType+' in '+(c.city||'your city')+'.':'Choose a different pond you have visited.',items:[{title:'Willow Pond',state:'Visited',effect:'Beginner pond',actions:[{label:'View pond',target:'TUT-3-04',kind:'navigate'}]}],actions:[{label:'Close',kind:'dismiss'}]};return null;}
async function setReaction(n,action){if(action.type==='NODE'&&action.navigation==='OVERLAY'){for(let ancestor=n;ancestor;ancestor=ancestor.parent){if(ancestor.id===action.destinationId){LEDGER.warnings.push({screen:LEDGER.overlays[ancestor.id]?.ownerId||null,action:n.name,kind:'navigate',target:action.destinationId,reason:'Self-overlay omitted: this source is inside its destination overlay, and no different result state is defined.'});return false;}}}await n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[action]}]);return true;}
async function wire(){const refs=new Set(BUNDLE.screens.filter(s=>s.reviewOnly||s.layout==='states').map(s=>s.id));let count=0;for(let i=0;i<PENDING_LINKS.length;i++){const p=PENDING_LINKS[i];if(p.close){if(p.timeout)await p.node.setReactionsAsync([{trigger:{type:'AFTER_TIMEOUT',timeout:p.timeout},actions:[{type:'CLOSE'}]}]);else if(await setReaction(p.node,{type:'CLOSE'})!==false)count++;continue;}if(p.detail){const o=createDetail(p.detail,p.ownerId);if(await setReaction(p.node,{type:'NODE',destinationId:o.id,navigation:'OVERLAY',transition:null})!==false)count++;continue;}const a=p.action||{};if(a.kind==='blocked'){const o=createToast(a.feedback||'This action is unavailable. Check the details and try again.',p.ownerId);if(await setReaction(p.node,{type:'NODE',destinationId:o.id,navigation:'OVERLAY',transition:null})!==false)count++;continue;}if(a.kind==='dismiss'&&!a.target){if(await setReaction(p.node,{type:'BACK'})!==false)count++;continue;}if(a.target==='DEX-P1-1'&&a.kind==='navigate')a.target='COOK-2a';const target=LEDGER.screens[a.target];if(target&&a.target!==p.ownerId&&!refs.has(a.target)){if(await setReaction(p.node,{type:'NODE',destinationId:target,navigation:'NAVIGATE',transition:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:.15},resetScrollPosition:true})!==false)count++;continue;}const reference=BUNDLE.screens.find(s=>s.id===a.target);if(refs.has(a.target)&&reference?.stateExamples?.length){if(a.target==='NPC-4-2'&&a.label==='Join'){LEDGER.warnings.push({screen:p.ownerId,action:a.label,kind:a.kind,target:a.target,reason:'Joined result is undefined; repeating the Joining overlay would not represent a completed join.'});continue;}let example=reference.stateExamples[0];if(a.target==='FISH-2'&&a.label==='Hook')example=reference.stateExamples.find(x=>x.title==='Reel')||example;if(a.label==='Pin')example=reference.stateExamples.find(x=>x.state==='Pinned')||example;if(/clue/i.test(a.label))example=reference.stateExamples.find(x=>/Clued/.test(x.state))||example;const o=createDetail(example,p.ownerId);if(await setReaction(p.node,{type:'NODE',destinationId:o.id,navigation:'OVERLAY',transition:null})!==false)count++;continue;}if(a.kind==='navigate'&&p.itemContext&&(a.target===p.ownerId||!target)){const detail={...p.itemContext,actions:(p.itemContext.actions||[]).filter(x=>!(x.kind==='navigate'&&x.target===p.ownerId))};const o=createDetail(detail,p.ownerId);if(await setReaction(p.node,{type:'NODE',destinationId:o.id,navigation:'OVERLAY',transition:null})!==false)count++;continue;}const ctx=contextDetail(a);if(ctx){const o=createDetail(ctx,p.ownerId);if(await setReaction(p.node,{type:'NODE',destinationId:o.id,navigation:'OVERLAY',transition:null})!==false)count++;continue;}
 // Missing destinations are an explicit handoff issue, never a fake success toast or unrelated screen.
 if(a.kind==='dismiss'){await setReaction(p.node,{type:'BACK'});count++;}
 else LEDGER.warnings.push({screen:p.ownerId,action:a.label,kind:a.kind,target:a.target||null,reason:refs.has(a.target)?'Target is a review-only state specimen.':'No valid outcome frame; no fake success was wired.'});
 }LEDGER.checks.prototypeReactions=count;}
function hasIconAncestor(n){for(let p=n.parent;p;p=p.parent)if(/^(Icon\/|Gensen Refactor\/Icon\/|Source icon fallbacks)/.test(p.name||''))return true;return false;}
function compactAuxiliaryMinimum(n){if(n.name==='Label')for(let p=n.parent;p;p=p.parent){if(/^Compact\/(Fish|Crop) cell ·/.test(p.name||''))return 9;if(p.name==='Compact/Profile content'&&(String(n.characters||'').startsWith('ID ')||['Following','Followers','Mutual','Close Friends','Fish-dex','Cookbook','Crop-dex','Passport'].includes(String(n.characters||''))))return 9;}if(['Title','Role'].includes(n.name))for(let p=n;p;p=p.parent){const main=p.type==='INSTANCE'?p.mainComponent:p;if(main&&/^Gensen Refactor\/Compact\/GearSlot/.test(main.name||main.parent?.name||''))return 9;if(main&&/^Gensen Refactor\/Compact\/GearSlot/.test(main.parent?.name||''))return 9;}return 10;}
function hasLightHudAncestor(n){for(let p=n;p;p=p.parent){const main=p.type==='INSTANCE'?p.mainComponent:p;if(main?.type==='COMPONENT'&&main.name==='Gensen Refactor/HUD'&&main.layoutMode==='NONE'&&main.width===344)return true;}return false;}
function hasCompactTypeAncestor(n){if(hasLightHudAncestor(n))return true;for(let p=n;p;p=p.parent){if(/^(Gensen Refactor\/Compact\/|Compact\/)/.test(p.name||''))return true;if(p.type==='INSTANCE'){const main=p.mainComponent;if(main&&(/^(Gensen Refactor\/Compact\/|Compact\/)/.test(main.name||'')||/^Gensen Refactor\/Compact\//.test(main.parent?.name||'')))return true;}}return false;}
function validate(){const frames=Object.values(LEDGER.screens);const all=PAGE.findAll(()=>true);const textNodes=all.filter(n=>n.type==='TEXT');const compactText=textNodes.filter(n=>typeof n.fontSize==='number'&&hasCompactTypeAncestor(n));const tiny=textNodes.filter(n=>typeof n.fontSize==='number'&&n.fontSize<(hasCompactTypeAncestor(n)?compactAuxiliaryMinimum(n):12)&&!hasIconAncestor(n));const unlinked=all.filter(n=>n.type==='INSTANCE'&&!n.mainComponent);const badSize=[];for(const id of frames){const n=all.find(x=>x.id===id);if(!n||n.width!==W||n.height!==H)badSize.push(id);}LEDGER.checks={...LEDGER.checks,screens:frames.length,stateExamples:BUNDLE.screens.reduce((n,s)=>n+(s.stateExamples||[]).length,0),components:Object.keys(LEDGER.components).length,componentSets:Object.keys(LEDGER.componentSets).length,instances:all.filter(n=>n.type==='INSTANCE').length,textNodes:textNodes.length,textBelow12:tiny.map(n=>n.id),compactAuxiliaryType:{minimumAllowed:10,quickSlotNameMinimum:10,roles:{'Compact/QuickSlot.Title':10,'Compact/GearSlot.Title/Role':9,'Compact readonly Profile ID/social labels/collection captions':9,'Compact auxiliary labels and counts':10,'Shared HUD auxiliary labels':10,'Core title':14,'Core effect':12},actualMinimum:compactText.length?Math.min(...compactText.map(n=>n.fontSize)):null,nodes:compactText.length,scope:'Compact components only; source-proportioned auxiliary text, user-requested visual benchmark'},orphanInstances:unlinked.map(n=>n.id),wrongScreenSizes:badSize,sceneImageOnly:true,originalNodesMutated:0,createdNodeIds:[PAGE.id,...all.map(n=>n.id)],visualInspection:'Not executed in cloud; inspect actual Figma render after import.'};if(frames.length!==288||tiny.length||unlinked.length||badSize.length)throw Error('Structural validation failed. Download ledger for details.');}
async function run(){if(busy)return;busy=true;stopRequested=false;try{if(figma.editorType!=='figma')throw Error('Open the Gensen Figma Design file.');const existing=figma.root.children.find(p=>p.name===RUN);if(existing){await figma.setCurrentPageAsync(existing);figma.viewport.scrollAndZoomIntoView(existing.children.slice(0,1));figma.ui.postMessage({type:'exists',text:'The review page already exists. No nodes were changed.',pageId:existing.id});return;}progress('Loading Nunito and reviewed design foundations…',2);await foundations();PAGE=figma.createPage();PAGE.name=RUN;await figma.setCurrentPageAsync(PAGE);LEDGER.pages.review=PAGE.id;LEDGER.status='building';LIBRARY=frame(PAGE,'Shared native components · edit here',1260,2000,'surface');LIBRARY.x=5000;LIBRARY.y=180;progress('Reusing source icon components and scene art…',5);await sourceAssets();await library();progress('Building all 288 editable screens…',12);for(let i=0;i<BUNDLE.screens.length;i++){if(stopRequested){LEDGER.status='paused-partial';LEDGER.warnings.push('Stopped at user request; partial review page preserved. No original pages changed.');figma.ui.postMessage({type:'stopped',ledger:LEDGER});return;}buildScreen(BUNDLE.screens[i],i);if(i%12===0){progress('Built '+(i+1)+' / 288 screens',12+Math.round(i/288*60));await new Promise(resolve=>setTimeout(resolve,0));}}progress('Connecting details, feedback and reviewed destinations…',76);await wire();PAGE.flowStartingPoints=['TUT-1','BAG-1','FARM-6','COOK-2a','FAC-1','MAP-2-FREE','MAP-4-PAID','BUFF-FARM'].filter(id=>LEDGER.screens[id]).map(id=>({nodeId:LEDGER.screens[id],name:id+' · refactored review'}));await Promise.all(STYLE_JOBS);progress('Validating native components and text sizes…',94);validate();LEDGER.status='imported-needs-visual-review';LEDGER.cloudExecuted=true;const first=await figma.getNodeByIdAsync(LEDGER.screens['BAG-1']);if(first)figma.viewport.scrollAndZoomIntoView([first]);figma.ui.postMessage({type:'complete',ledger:LEDGER});}catch(error){LEDGER.status='failed';LEDGER.error=String(error.stack||error);figma.ui.postMessage({type:'error',text:String(error.message||error),ledger:LEDGER});}finally{busy=false;}}
figma.showUI(__html__,{width:440,height:520,themeColors:true});
figma.ui.onmessage=async message=>{if(message.type==='build')await run();else if(message.type==='stop')stopRequested=true;else if(message.type==='inspect')figma.ui.postMessage({type:'inspect',screens:BUNDLE.screens.length,stateExamples:BUNDLE.screens.reduce((n,s)=>n+(s.stateExamples||[]).length,0),runName:RUN,existing:figma.root.children.some(p=>p.name===RUN)});};
